import{_ as t,o as s,c as a,ag as i}from"./chunks/framework.CrXGS008.js";const k=JSON.parse('{"title":"HTTP API","description":"","frontmatter":{},"headers":[],"relativePath":"nay-lib/api.md","filePath":"nay-lib/api.md"}'),d={name:"nay-lib/api.md"};function n(o,e,r,l,p,h){return s(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="http-api" tabindex="-1">HTTP API <a class="header-anchor" href="#http-api" aria-label="Permalink to &quot;HTTP API&quot;">​</a></h1><p>Scripts and websites (dashboards, Discord bots, shops) can read and change the server through a JSON API served by FXServer on the game port:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://&lt;server ip&gt;:&lt;port&gt;/&lt;resource&gt;/v1/&lt;route&gt;</span></span></code></pre></div><h2 id="turn-it-on" tabindex="-1">Turn it on <a class="header-anchor" href="#turn-it-on" aria-label="Permalink to &quot;Turn it on&quot;">​</a></h2><p>The API is <strong>off by default</strong>. Turn it on in <code>/nay</code>, on the <strong>Nayretis</strong> page: <strong>HTTP API</strong> (<code>ApiEnabled</code>). While it is off, every route answers <code>503 api_disabled</code>. <strong>Maximum request size (KB)</strong> (<code>ApiMaxBodyKb</code>) bounds request bodies (1024 KB by default).</p><h2 id="tokens" tabindex="-1">Tokens <a class="header-anchor" href="#tokens" aria-label="Permalink to &quot;Tokens&quot;">​</a></h2><p>Create tokens in the <strong>API</strong> tab of <code>/nay</code> (the token is shown once: copy it then) or from the server console:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>nay_api_token create &lt;label&gt; &lt;scope...&gt;</span></span>
<span class="line"><span>nay_api_token list</span></span>
<span class="line"><span>nay_api_token revoke &lt;id&gt;</span></span></code></pre></div><p>A token looks like <code>nay_&lt;id&gt;_&lt;secret&gt;</code>. Only its SHA-256 hash is stored. Each token has its scopes, optional allowed addresses (IPv4, IPv6 or CIDR ranges), a request limit per minute and an optional expiry.</p><p>Scopes are <code>&lt;resource&gt;.&lt;scope&gt;</code>, with wildcards: <code>nay_car_wash.*</code> gives every route of a script, <code>*</code> gives everything. Each script lists its routes and scopes on its own page, for example <a href="/car-wash/api">Car Wash</a>.</p><h2 id="requests" tabindex="-1">Requests <a class="header-anchor" href="#requests" aria-label="Permalink to &quot;Requests&quot;">​</a></h2><ul><li>Send <code>Authorization: Bearer &lt;token&gt;</code>.</li><li>Bodies are JSON (<code>Content-Type: application/json</code>) with a <code>Content-Length</code>. Chunked bodies are refused.</li><li>After 10 failed authentications within a minute, requests without a valid token from that address are refused for 5 minutes. Valid tokens keep working.</li><li>Behind a reverse proxy, set <code>nay:apiTrustedProxies</code> (see <a href="#https">HTTPS</a>). Otherwise every caller shares the proxy address.</li></ul><p>Every answer is JSON with an <code>X-Request-Id</code> header:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;ok&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;data&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { } }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;ok&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;error&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;code&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;forbidden&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;message&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;This token does not allow this route&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;details&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { } } }</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Status</th><th>Code</th><th>Meaning</th></tr></thead><tbody><tr><td>400</td><td><code>unexpected_body</code>, <code>invalid_json</code>, <code>invalid_request</code></td><td>Body sent to a route without body, body not valid JSON, or malformed <code>Content-Length</code>.</td></tr><tr><td>401</td><td><code>unauthorized</code></td><td>Missing, unknown, revoked or expired token.</td></tr><tr><td>403</td><td><code>forbidden</code>, <code>ip_not_allowed</code></td><td>The token lacks the scope, or the address is not allowed for it.</td></tr><tr><td>404 / 405</td><td><code>not_found</code>, <code>method_not_allowed</code></td><td>Unknown route, or wrong method on a known route.</td></tr><tr><td>411</td><td><code>length_required</code></td><td>Any <code>Transfer-Encoding</code> (chunked body).</td></tr><tr><td>413</td><td><code>payload_too_large</code></td><td>Body over <code>ApiMaxBodyKb</code>. An announced <code>Content-Length</code> over 10 MB is refused before the body is read.</td></tr><tr><td>415</td><td><code>unsupported_media_type</code></td><td>Body that is not <code>application/json</code>.</td></tr><tr><td>422</td><td><code>invalid_request</code>, <code>unknown_parameter</code>, <code>invalid_value</code></td><td>Parameter, query or body failing validation (<code>details.path</code> and <code>details.reason</code>).</td></tr><tr><td>429</td><td><code>rate_limited</code>, <code>too_many_failures</code></td><td>Token over its limit per minute, or address blocked. See <code>Retry-After</code>.</td></tr><tr><td>500</td><td><code>internal_error</code></td><td>The route failed. See the server console.</td></tr><tr><td>503</td><td><code>api_disabled</code>, <code>not_ready</code></td><td>API off, or resource still starting (<code>Retry-After</code>).</td></tr><tr><td>504</td><td><code>timeout</code></td><td>The route did not answer within 10 seconds. It keeps running: a change may still be applied after the 504, so read the state back before retrying.</td></tr></tbody></table><h2 id="nay-lib-routes" tabindex="-1">nay_lib routes <a class="header-anchor" href="#nay-lib-routes" aria-label="Permalink to &quot;nay_lib routes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Method</th><th>Route</th><th>Scope</th><th>Data</th></tr></thead><tbody><tr><td>GET</td><td><code>/nay_lib/v1/status</code></td><td><code>nay.status</code></td><td>Server name, players, max players, framework, inventory, target, Nayretis resources and versions.</td></tr><tr><td>GET</td><td><code>/nay_lib/v1/players</code></td><td><code>nay.players</code></td><td>Connected players: id, name, character, identifier, job.</td></tr><tr><td>GET</td><td><code>/nay_lib/v1/settings/:resource</code></td><td><code>nay.settings</code> plus <code>&lt;resource&gt;.config</code> or <code>nay.config</code></td><td>Settings of a script with their values.</td></tr><tr><td>PUT</td><td><code>/nay_lib/v1/settings/:resource/:key</code></td><td>same</td><td>Changes a setting. Body <code>{ &quot;value&quot;: ... }</code>.</td></tr><tr><td>DELETE</td><td><code>/nay_lib/v1/settings/:resource/:key</code></td><td>same</td><td>Resets a setting to its default.</td></tr><tr><td>GET</td><td><code>/nay_lib/v1/audit</code></td><td><code>nay.audit</code></td><td>Audit log, 50 rows per page. Query <code>resource</code>, <code>action</code>, <code>actor</code>, <code>from</code> and <code>to</code> (Unix seconds), <code>page</code>.</td></tr></tbody></table><p>Every call that changes something is written to the <a href="/nay-lib/audit">audit log</a> (<code>api.call</code>, actor <code>api:&lt;token label&gt;</code>).</p><h2 id="https" tabindex="-1">HTTPS <a class="header-anchor" href="#https" aria-label="Permalink to &quot;HTTPS&quot;">​</a></h2><p>FXServer only speaks plain HTTP: anyone on the way can read a token sent over it. Put a reverse proxy with a certificate in front of the API and only expose the routes you use. Then tell <code>nay_lib</code> which proxies to trust, so allowed addresses and rate limits apply to the real client address taken from <code>X-Forwarded-For</code>:</p><div class="language-cfg vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cfg</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>set nay:apiTrustedProxies &quot;127.0.0.1&quot;</span></span></code></pre></div><p>The value is a comma separated list of addresses or CIDR ranges.</p><p>nginx:</p><div class="language-nginx vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">nginx</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">server</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">	listen </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">443</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ssl;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">	server_name </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">api.example.com;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">	ssl_certificate </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/etc/letsencrypt/live/api.example.com/fullchain.pem;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">	ssl_certificate_key </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/etc/letsencrypt/live/api.example.com/privkey.pem;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">	location</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> ~</span><span style="--shiki-light:#032F62;--shiki-dark:#DBEDFF;"> ^/(nay_lib|nay_car_wash)/v1/ </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">		proxy_pass </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">http://127.0.0.1:30120;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">		proxy_set_header </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">X-Forwarded-For $remote_addr;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">		client_max_body_size </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1m</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">	}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Caddy (certificate obtained automatically):</p><div class="language-caddy vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">caddy</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>api.example.com {</span></span>
<span class="line"><span>	@nayretis path_regexp ^/(nay_lib|nay_car_wash)/v1/</span></span>
<span class="line"><span>	reverse_proxy @nayretis 127.0.0.1:30120</span></span>
<span class="line"><span>}</span></span></code></pre></div>`,26)])])}const u=t(d,[["render",n]]);export{k as __pageData,u as default};
